namespace Sample.Worker.Messaging;

public sealed class Installer
{
    public void Install(IServiceCollection services)
    {
        services.AddBroker();
        services.AddBrokerExtension<BrokerExtension>();
    }
}

public sealed class BrokerExtension : IBrokerExtension
{
    public void Configure(BrokerOptions opts)
    {
        opts.Policies.DisableConventionalLocalRouting();
        opts.UseQueueTransport(Connect);
        opts.BindExchange("order-placed").ToQueue("sample-worker-order-placed");
        opts.ListenToQueue("sample-worker-order-placed").DeadLetterQueueing(new DeadLetterQueue("sample-worker-order-placed-dlq"));
    }
}
